import { ToolboxIcon as WrenchIcon } from '@solar-icons/react/linear/toolbox'
import * as React from 'react'

import { TimelineConnector, TimelineStatusIcon } from '@/components/ai/timeline-status'
import { cn } from 'cn'

interface ToolTimelineItem {
  detail?: string
  id: string
  status: 'complete' | 'pending' | 'running'
  target?: string
  time?: string
  verb: string
}

interface ToolTimelineProps extends React.ComponentProps<'section'> {
  items: ToolTimelineItem[]
  summary?: string
  title?: string
}

const rowTone = {
  complete: { verb: 'text-muted-foreground', target: 'text-foreground/70' },
  running: { verb: 'text-muted-foreground', target: 'text-foreground' },
  pending: { verb: 'text-muted-foreground/55', target: 'text-muted-foreground/55' },
}

function ToolTimeline({
  className,
  items,
  summary,
  title = 'Tool timeline',
  ...props
}: ToolTimelineProps) {
  return (
    <section
      data-slot="tool-timeline"
      className={cn(
        'rounded-[16px] bg-card p-4 font-sans text-sm font-[450] tracking-[-0.05px] text-muted-foreground shadow-card',
        className,
      )}
      {...props}
    >
      <header className="flex items-center gap-2">
        <WrenchIcon className="size-4 text-muted-foreground" />
        <h3 className="text-sm leading-5 font-medium text-muted-foreground">{title}</h3>
        {summary && (
          <span className="ml-auto text-[13px] leading-5 text-muted-foreground/70">{summary}</span>
        )}
      </header>

      <ol className="mt-4">
        {items.map((item, index) => {
          const next = items[index + 1]
          const tone = rowTone[item.status]
          const isFile = item.target ? /\.[a-z0-9]+$/i.test(item.target) : false

          return (
            <li
              className="relative flex gap-3 pb-5 transition-opacity duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] last:pb-0 starting:opacity-0"
              key={item.id}
            >
              {next && <TimelineConnector reached={next.status !== 'pending'} />}
              <TimelineStatusIcon className="mt-0.5" status={item.status} />
              <div className="min-w-0 flex-1">
                <div className="flex items-baseline gap-3">
                  <p className="min-w-0 flex-1 truncate text-sm leading-5">
                    <span className={tone.verb}>{item.verb}</span>
                    {item.target && (
                      <>
                        {' '}
                        <span
                          className={cn(
                            'font-medium',
                            tone.target,
                            isFile && 'font-mono text-[13px] font-normal',
                          )}
                        >
                          {item.target}
                        </span>
                      </>
                    )}
                  </p>
                  {item.time && (
                    <time
                      className={cn(
                        'shrink-0 font-mono text-[11px] tabular-nums',
                        item.status === 'running'
                          ? 'text-foreground/70'
                          : 'text-muted-foreground/70',
                      )}
                    >
                      {item.time}
                      {item.status === 'running' && '…'}
                    </time>
                  )}
                </div>
                {item.detail && (
                  <p className="mt-0.5 text-xs leading-4 text-muted-foreground/70">{item.detail}</p>
                )}
              </div>
            </li>
          )
        })}
      </ol>
    </section>
  )
}

export { ToolTimeline }
export type { ToolTimelineItem, ToolTimelineProps }

import { LoaderIcon as LoaderCircleIcon } from '@solar-icons/react/linear/loader'

import { cn } from 'cn'

type TimelineStatus = 'complete' | 'pending' | 'running'

const timelineLabelTone: Record<TimelineStatus, string> = {
  complete: 'text-muted-foreground',
  pending: 'text-muted-foreground/55',
  running: 'text-foreground',
}

const timelineDetailTone: Record<TimelineStatus, string> = {
  complete: 'text-muted-foreground/55',
  pending: 'text-muted-foreground/45',
  running: 'text-muted-foreground',
}

const timelineStatusLabel: Record<TimelineStatus, string> = {
  complete: 'Complete',
  pending: 'Pending',
  running: 'Running',
}

function TimelineStatusIcon({ className, status }: { className?: string; status: TimelineStatus }) {
  return (
    <span className={cn('flex size-4 shrink-0 items-center justify-center', className)}>
      {status === 'complete' ? (
        <svg
          aria-hidden="true"
          className="size-3.5 text-muted-foreground transition-[opacity,scale] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] starting:scale-90 starting:opacity-0 motion-reduce:starting:scale-100"
          fill="none"
          stroke="currentColor"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth="1.75"
          viewBox="0 0 16 16"
        >
          <path d="m3.5 8.5 3 3 6-7" />
        </svg>
      ) : status === 'running' ? (
        <LoaderCircleIcon
          aria-hidden="true"
          className="size-3.5 animate-spin text-blue-500 motion-reduce:animate-none dark:text-blue-400"
        />
      ) : (
        <span
          aria-hidden="true"
          className="size-3 rounded-full border-[1.5px] border-muted-foreground/45"
        />
      )}
      <span className="sr-only">{timelineStatusLabel[status]}</span>
    </span>
  )
}

function TimelineConnector({ reached }: { reached: boolean }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        'absolute top-6 bottom-1 left-2 w-px -translate-x-1/2 transition-colors duration-200 ease-out',
        reached ? 'bg-foreground/25' : 'bg-foreground/8',
      )}
    />
  )
}

export { TimelineConnector, TimelineStatusIcon, timelineDetailTone, timelineLabelTone }
export type { TimelineStatus }
